1|/**
2| * Stashov — pasted-routine parser.
3| *
4| * Turns a TikTok/YouTube caption, a product list, or a hand-written routine
5| * into the same protocol shape the Rules tab already renders. This is
6| * deliberately deterministic: no API key is required, and the output stays
7| * editable before it is saved.
8| */
9|
10|const CATEGORY_RULES = [
11|  { category: 'Fragrances & Cologne', re: /(fragrance|perfume|cologne|eau de|edp|oud|scent|deodorant)/i },
12|  { category: 'Skincare, Health & Protocols', re: /(skincare|skin care|cleanser|serum|retinol|retinoid|adapalene|niacinamide|azelaic|spf|sunscreen|moisturi[sz]er|exfoliat|toner|acne|dark spot|peptide|collagen|lactoferrin|supplement|vitamin|creatine|sleep|workout|gym|diet)/i },
13|  { category: 'Programming, Cloud & Dev Tools', re: /(code|coding|programming|javascript|typescript|python|react|git|docker|kubernetes|sql|api)/i },
14|  { category: 'Business, Finance & Auto/Real Estate', re: /(invest|investing|budget|finance|business|marketing|sales|startup)/i },
15|];
16|
17|const PHASE_HEADER = /^(am|a\.m\.|morning|day|daytime|pm|p\.m\.|evening|night|nighttime)(\s+(routine|steps?|care))?\s*:?\s*$/i;
