125|/**
126| * Keep only the finished report. Models sometimes narrate their analysis before
127| * answering; the prompt asks for the report after @@REPORT@@, and this drops
128| * everything before that marker. A response without a marker is returned as-is
129| * so an older or non-compliant model still produces a usable report.
130| */
131|function extractReport(content) {
132|  const text = String(content == null ? '' : content).replace(/\r\n/g, '\n').trim();
133|  if (!text) return '';
134|  const index = text.lastIndexOf(REPORT_MARKER);
135|  if (index !== -1) {
136|    const tail = text.slice(index + REPORT_MARKER.length).trim().replace(/^:\s*/, '');
137|    if (tail) return tail;
138|  }
139|  const first = text.indexOf(REPORT_MARKER);
140|  if (first !== -1) {
141|    const tail = text.slice(first + REPORT_MARKER.length).trim().replace(/^:\s*/, '');
142|    if (tail) return tail;
143|  }
144|  return text;
145|}
146|
147|/**
148| * Turn a provider response into the numbers the telemetry console shows.
149| * Tokens come from the provider when it reports them; a failed fallback call
150| * records zero rather than a made-up 84,500. Spend is a blended estimate and
151| * the Router labels it as such; override the rate with
152| * TELEMETRY_USD_PER_M_TOKENS (USD per million tokens).
153| */
154|function usageFromResult(result) {
155|  const usage = (result && result.usage) || null;
156|  const tokensIn = Math.max(0, Math.round(Number(usage && usage.prompt_tokens) || 0));
157|  const tokensOut = Math.max(0, Math.round(Number(usage && usage.completion_tokens) || 0));
158|  const configuredRate = Number(process.env.TELEMETRY_USD_PER_M_TOKENS);
159|  const rate = Number.isFinite(configuredRate) && configuredRate >= 0
160|    ? configuredRate
161|    : BLENDED_USD_PER_MILLION;
162|  const cost = Number((((tokensIn + tokensOut) / 1_000_000) * rate).toFixed(5));
163|  return {
164|    live: Boolean(result && result.live),
165|    latency: Math.max(0, Math.round(Number(result && result.latency_ms) || 0)),
166|    tokensIn,
167|    tokensOut,
168|    cost,
169|  };
170|}
171|
172|module.exports = {
173|  buildBookmarkDigest,
174|  buildFallbackReport,
175|  buildVaultAuditMessages,
176|  extractReport,
177|  usageFromResult,
178|};

